CREATE DATABASE IF NOT EXISTS `spm_fiscal` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `spm_fiscal`;

-- --------------------------------------------------------
-- 1. Tabela users
-- --------------------------------------------------------
DROP TABLE IF EXISTS `user_passwords`;
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` VARCHAR(64) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `email` VARCHAR(255) NOT NULL,
  `role` ENUM('ADMIN', 'MANAGER', 'AUDITOR') NOT NULL DEFAULT 'AUDITOR',
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `last_login` DATETIME NULL,
  `avatar` TEXT NULL,
  `department` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_users_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- 2. Tabela user_passwords
-- --------------------------------------------------------
CREATE TABLE `user_passwords` (
  `email` VARCHAR(255) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`email`),
  CONSTRAINT `fk_user_passwords_email` FOREIGN KEY (`email`) REFERENCES `users` (`email`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- 3. Tabela invoices
-- --------------------------------------------------------
DROP TABLE IF EXISTS `invoices`;
CREATE TABLE `invoices` (
  `id` VARCHAR(64) NOT NULL,
  `nome` VARCHAR(255) NOT NULL DEFAULT '',
  `documento` VARCHAR(64) NOT NULL DEFAULT '',
  `data_saida` VARCHAR(64) NOT NULL DEFAULT '',
  `endereco` TEXT NULL,
  `bairro` VARCHAR(255) NOT NULL DEFAULT '',
  `cep` VARCHAR(32) NOT NULL DEFAULT '',
  `municipio` VARCHAR(255) NOT NULL DEFAULT '',
  `uf` VARCHAR(10) NOT NULL DEFAULT '',
  `fatura` VARCHAR(64) NOT NULL DEFAULT '',
  `valor_produtos` VARCHAR(64) NOT NULL DEFAULT '0,00',
  `valor_nota` VARCHAR(64) NOT NULL DEFAULT '0,00',
  `desconto` VARCHAR(64) NOT NULL DEFAULT '0,00',
  `codigo` VARCHAR(128) NOT NULL DEFAULT '',
  `quantidade` VARCHAR(64) NOT NULL DEFAULT '1',
  `descricao` TEXT NULL,
  `cor` VARCHAR(64) NOT NULL DEFAULT 'Não identificada',
  `origem` VARCHAR(64) NOT NULL DEFAULT 'Outros',
  `origem_arquivo` VARCHAR(255) NULL,
  `data_upload` VARCHAR(64) NULL,
  `status` VARCHAR(32) NOT NULL DEFAULT 'Processado',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  INDEX `idx_invoices_documento` (`documento`),
  INDEX `idx_invoices_origem` (`origem`),
  INDEX `idx_invoices_cor` (`cor`),
  INDEX `idx_invoices_uf` (`uf`),
  INDEX `idx_invoices_municipio` (`municipio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- 4. Tabela audit_logs
-- --------------------------------------------------------
DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` VARCHAR(64) NOT NULL,
  `timestamp` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `user_id` VARCHAR(64) NOT NULL,
  `user_name` VARCHAR(255) NOT NULL,
  `action` VARCHAR(255) NOT NULL,
  `category` VARCHAR(64) NOT NULL,
  `details` TEXT NOT NULL,
  `ip` VARCHAR(64) NOT NULL DEFAULT '127.0.0.1',
  `severity` ENUM('info', 'warning', 'error', 'success') NOT NULL DEFAULT 'info',
  PRIMARY KEY (`id`),
  INDEX `idx_audit_logs_timestamp` (`timestamp`),
  INDEX `idx_audit_logs_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- 5. Tabela alert_rules
-- --------------------------------------------------------
DROP TABLE IF EXISTS `alert_rules`;
CREATE TABLE `alert_rules` (
  `id` VARCHAR(64) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `type` VARCHAR(64) NOT NULL,
  `threshold` DECIMAL(12,2) NULL,
  `email_notify` TINYINT(1) NOT NULL DEFAULT 1,
  `push_notify` TINYINT(1) NOT NULL DEFAULT 1,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `last_triggered` DATETIME NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- 6. Tabelas system_settings & integrations_config
-- --------------------------------------------------------
DROP TABLE IF EXISTS `system_settings`;
CREATE TABLE `system_settings` (
  `id` VARCHAR(32) NOT NULL,
  `data_json` JSON NOT NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integrations_config`;
CREATE TABLE `integrations_config` (
  `type` VARCHAR(32) NOT NULL,
  `data_json` JSON NOT NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

